import { GameState } from "../types"

export const checkTalent = (state: GameState, talentId: string | string[]) => {
    if(typeof talentId === 'string') {
        return state.talents.filter((talent) => talent.id === talentId)?.every((talent) => talent.state !== 'active')
    } else {
        return !talentId.some((id) => state.talents.filter((talent) => talent.id === id)?.some((talent) => talent.state === 'active'))
    }
}

export const createFlagsAndPutInState = (state: GameState, startingFlags: number) => {
    for (let i = 0; i < startingFlags; i++) {
        state.flags.push({
          id: `flag-${Date.now()}-${i}`,
          x: 0,
          y: 0,
          countryId: undefined
        });
      }
};