import { GameState, NewsItem } from "../../types";
import { News as NEWS } from "../../News";
import { NEWS_INTERVAL } from "../../News";

function getNewsForState(state: GameState): string[] {
  // Получаем новости для текущего этапа игры
  return Object.values(NEWS).reduce<string[]>((acc, news) => {
    if (news.stage === state.stage) {
      acc.push(news.id);
    }
    return acc;
  }, []);
}

// Функция для выбора случайной новости, соответствующей текущему этапу игры
function selectNews(state: GameState): [string | null, string[]] {
  // Если есть новости в очереди, берем первую
  if (state.newsQueue.length > 0) {
    const newsId = state.newsQueue[0];
    const newsQueue = state.newsQueue.slice(1);
    return [newsId, newsQueue];
  }

  // Если очередь пуста, выбираем случайную новость для текущего этапа
  const availableNews = getNewsForState(state);
  if (availableNews.length > 0) {
    const randomIndex = Math.floor(Math.random() * availableNews.length);
    const selectedNews = availableNews[randomIndex];
    return [selectedNews, state.newsQueue];
  }

  // Если новостей нет, оставляем текущую
  return [state.activeNews, state.newsQueue];
}

// Функция для проверки необходимости отображения новостей
export function checkNews(state: GameState): [string | null, string[], number] {
  const now = Date.now();
  let activeNews = state.activeNews;
  let newsQueue = state.newsQueue;
  let lastNewsTime = state.lastNewsTime;
  
  // Проверяем, прошло ли достаточно времени для смены новости (30 сек)
  const shouldChangeNews = (now - state.lastNewsTime > NEWS_INTERVAL) || 
                          (state.newsQueue.length > 0) || 
                          (!state.activeNews);
  
  if (shouldChangeNews) {
    lastNewsTime = now;
    [activeNews, newsQueue] = selectNews(state);
  }
  
  // Возвращаем обновленное состояние новостей
  return [activeNews, newsQueue, lastNewsTime];
} 